import exported from "@subrosa/chat-core/agent-lite.json";

/**
 * What the web client knows of agent-lite and of the sync codec, generated by
 * Rust (`src-tauri/src/agent_lite/web_client_export.rs`) so neither the
 * prompt prose nor the table allowlist is written a second time here.
 */
export interface AgentLiteExport {
  systemPrompt: string;
  defaultModel: string;
  finalAnswerNudge: string;
  memoryBlockHeader: string;
  injectedMemoryLimit: number;
  personalization: {
    header: string;
    about: string;
    style: string;
    personality: string;
    maxFieldChars: number;
    personalities: Record<string, string>;
  };
  limits: { maxToolRounds: number; webSearchResults: number; webPageChars: number };
  tools: ToolDefinition[];
  tables: Record<TableName, { kind: SyncKind; columns: string[] }>;
}
export interface ToolDefinition {
  type: "function";
  function: { name: string; description: string; parameters: Record<string, unknown> };
}

export const AGENT_LITE = exported as unknown as AgentLiteExport;

/** The routing classes a browser device reads and writes. Bounded on purpose:
 * the page holds a decryption key, so what it may pull is a decision. */
export const WEB_KINDS = ["conversation", "memory", "note", "folder"] as const;
export type SyncKind = (typeof WEB_KINDS)[number];

export type TableName =
  | "agent_tasks"
  | "agent_messages"
  | "memories"
  | "notes"
  | "folders"
  | "account_session_folders";

export type Cell = string | number | null;
export type Row = Record<string, Cell>;

/** The authenticated body table of a custom assistant's conversation. It is
 * read like `agent_tasks` and never written from a browser. */
const ASSISTANT_CONVERSATIONS = "assistant_conversations";

export function tableOf(name: string): { name: TableName; kind: SyncKind; columns: string[] } {
  const resolved = name === ASSISTANT_CONVERSATIONS ? "agent_tasks" : name;
  const table = AGENT_LITE.tables[resolved as TableName];
  if (!table) throw new Error("Unknown synchronised table");
  return { name: resolved as TableName, ...table };
}

/** A row as it travels: every allowlisted column, nothing else. A column the
 * caller did not name travels as null, the way SQLite would have stored it. */
export function travellingRow(name: TableName, values: Row): Row {
  const { columns } = tableOf(name);
  const row: Row = {};
  for (const column of columns) {
    const value = values[column];
    if (value !== undefined) row[column] = value;
    else if (!(name === "memories" && column === "scope")) row[column] = null;
  }
  return row;
}

/** Whether a received row only names columns the codec allows, with values a
 * column can hold. The same check `account/sync.rs` makes before applying. */
export function validRow(name: string, row: unknown): row is Row {
  if (!row || typeof row !== "object" || Array.isArray(row)) return false;
  let columns: string[];
  try {
    columns = tableOf(name).columns;
  } catch {
    return false;
  }
  return Object.entries(row as Record<string, unknown>).every(
    ([key, value]) =>
      columns.includes(key) &&
      (value === null || typeof value === "string" || typeof value === "number"),
  );
}

/** Timestamps as the app writes them: RFC 3339 with milliseconds, in UTC. */
export function timestamp(now = new Date()): string {
  return now.toISOString();
}
